#!/usr/bin/env bash
# Autogenerated test: runs as the remote user inside a container built from each compatibility image with apptainer
# installed (the feature has no options), under the security options the feature declares.
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib
# shellcheck source=/dev/null
source "$(dirname "$0")/helpers.sh"

work_dir="$(mktemp -d)"

# The version the feature's source offers when the test runs: each source installs its current version, so no literal
# can name it (helpers.sh, source_candidate).
candidate="$(source_candidate)"

check "apptainer runs for the remote user" apptainer --version
check "apptainer reports the version the source ships (${candidate:-none})" version_reports "${candidate}"
check "the source definition is the one the feature writes for this image" source_is_expected
check "the source is defined once" source_defined_once
check "the key file holds only the pinned key" key_is_pinned
check "the non-setuid package is installed and no file under ${APPTAINER_LIBEXEC_DIR} is setuid" non_setuid
check "the package's files and configuration are unchanged" package_files_unchanged
check "the container is not privileged and has no added capability" container_metadata
check "the remote user creates a user namespace and mounts inside it" userns_with_mount
check "the remote user builds a sandbox from an OCI image and runs a command in it" sandbox_runs "${work_dir}/alpine"
check "no temporary install directory remains" no_temporary_dir

rm -rf "${work_dir}"
reportResults
